 private var privateVibeId:String?=null;private var pendingPrivateVibe:String?=null;private var vibeViewed=false;private var privateVibeLoaded=false;private var privateVibePaused=false
 @Volatile private var navigationBusy=false;private var navigationOwner="";private var navigationState=JSONObject()
 private data class NavigationTarget(val key:String,val host:java.lang.ref.WeakReference<FrameLayout>,var painted:String?=null)
 private val navigationTargets=mutableListOf<NavigationTarget>()
 private fun navigationBadge(host:FrameLayout,key:String){val owner=prefs.getString("server","")+"/"+prefs.getString("id","");if(navigationOwner!=owner){navigationOwner=owner;navigationState=JSONObject();navigationTargets.clear()};navigationTargets.add(NavigationTarget(key,java.lang.ref.WeakReference(host)));paintNavigation()}
 private fun paintNavigation(){navigationTargets.removeAll {it.host.get()==null};for(target in navigationTargets){val key=target.key;val host=target.host.get()?:continue
  val activeState=navigationState.optJSONObject("vibes")?.optJSONObject(key);val signature=if(key in listOf("chat","calls","vibe"))navigationState.optInt(when(key){"calls"->"missed_calls";"vibe"->"unseen_vibes";else->"unread_messages"}).toString() else if(activeState!=null&&activeState.optLong("expires")*1000>System.currentTimeMillis())activeState.toString() else "";if(target.painted==signature&&host.findViewWithTag<View>("navigation-state-badge")!=null)continue;target.painted=signature
  host.findViewWithTag<View>("navigation-state-badge")?.let {host.removeView(it)}
  if(key in listOf("chat","calls","vibe")){val field=when(key){"calls"->"missed_calls";"vibe"->"unseen_vibes";else->"unread_messages"};val label=when(key){"calls"->"unseen missed calls";"vibe"->"unseen Vibe posts";else->"unread messages"};val count=navigationState.optInt(field);if(count>0)host.addView(text(if(count>99)"99+" else count.toString(),10f).apply {tag="navigation-state-badge";contentDescription="$count $label";gravity=Gravity.CENTER;includeFontPadding=false;minimumWidth=dp(17);setPadding(dp(3),0,dp(3),0);setTextColor(Color.WHITE);background=GradientDrawable().apply {setColor(Color.rgb(229,57,69));cornerRadius=dp(99).toFloat()}},FrameLayout.LayoutParams(-2,dp(17),Gravity.TOP or Gravity.END))}
  else{val active=navigationState.optJSONObject("vibes")?.optJSONObject(key);if(active!=null&&active.optLong("expires")*1000>System.currentTimeMillis()){host.clipChildren=false;host.clipToPadding=false;host.clipToOutline=false;val badge=FrameLayout(this).apply {tag="navigation-state-badge";contentDescription="View active Vibe";isClickable=true;isFocusable=true;addView(svgIcon("vibe-icon"),FrameLayout.LayoutParams(-1,-1));setOnClickListener {showGaming(page="/vibe.html",vibeRoute="item="+active.getString("item")+"&visibility="+active.getString("visibility"))}};host.addView(badge,FrameLayout.LayoutParams(dp(17),dp(17),Gravity.BOTTOM or Gravity.END))}}
 }}
 private fun syncNavigationState(){if(navigationBusy||prefs.getString("token","").isNullOrEmpty())return;val owner=prefs.getString("server","")+"/"+prefs.getString("id","");if(navigationOwner!=owner){navigationOwner=owner;navigationState=JSONObject();navigationTargets.clear()};navigationBusy=true;val client=api();net.execute {try{val state=client.request("/navigation/state");main.post {if(client.token==prefs.getString("token","")&&state.optString("account")==prefs.getString("id","")){navigationState=state;paintNavigation()}}}catch(_:Exception){}finally{navigationBusy=false}}}
 private fun attachVibeSwipe(surface:View,panel:View,onTap:((Float)->Unit)?=null,finish:()->Unit){var startX=0f;var startY=0f;var started=0L;var dragging=false
  surface.setOnTouchListener {v,e->when(e.actionMasked){android.view.MotionEvent.ACTION_DOWN->{startX=e.rawX;startY=e.rawY;started=android.os.SystemClock.elapsedRealtime();dragging=false;if(panel.findFocus() is EditText)panel.findFocus()?.clearFocus();true};android.view.MotionEvent.ACTION_MOVE->{val dy=e.rawY-startY;if(dy>dp(7)&&kotlin.math.abs(e.rawX-startX)<dy){dragging=true;v.parent?.requestDisallowInterceptTouchEvent(true);panel.animate().cancel();panel.translationY=dy.coerceAtLeast(0f)};true};android.view.MotionEvent.ACTION_UP->{val dy=(e.rawY-startY).coerceAtLeast(0f);if(dragging&&VibeDismiss.shouldClose(dy/resources.displayMetrics.density,android.os.SystemClock.elapsedRealtime()-started,panel.height/resources.displayMetrics.density)){panel.animate().translationY(panel.height.toFloat()).setDuration(motion(160L)).withEndAction {finish()}.start()}else{panel.animate().translationY(0f).setDuration(motion(160L)).start();if(!dragging){if(onTap!=null)onTap((e.x/v.width.coerceAtLeast(1)).coerceIn(0f,1f))else v.performClick()}};true};android.view.MotionEvent.ACTION_CANCEL->{panel.animate().translationY(0f).setDuration(motion(160L)).start();true};else->false}}
 }
 private fun showContent(view:View){setShowWhenLocked(screen=="call");setTurnScreenOn(screen=="call");if(viewOnceId!=null||protectedSessionId!=null||privateVibeId!=null||openingOnce)window.addFlags(WindowManager.LayoutParams.FLAG_SECURE);setContentView(view);applyAppearance(view);refreshPaletteViews(view);if(screen=="profile"||screen=="people"&&homeCalls){view.alpha=.5f;view.translationY=dp(7).toFloat();view.animate().alpha(1f).translationY(0f).setDuration(motion(170L)).start()};if(viewOnceId==null&&protectedSessionId==null&&privateVibeId==null&&!openingOnce)window.clearFlags(WindowManager.LayoutParams.FLAG_SECURE)}
 private fun applyAppearance(view:View,settingsSurface:Boolean=false){
  val settingsText=settingsSurface||view.tag=="settings-text"
  if(view.background is OrbitWallpaper)view.background.invalidateSelf()
  if(view.hasOnClickListeners()||view is EditText){view.isFocusable=true;view.foreground=if(view.tag=="chat-draft")null else OrbitPalette.focus(this,bright)}
  val bg=view.background
  val color=when(bg){is GradientDrawable->bg.color?.defaultColor;is android.graphics.drawable.ColorDrawable->bg.color;else->null}
  val replacement=when{
   view.tag=="message-body"||view.tag=="chat-draft"->null
   view.tag=="chat-reading-surface"->(surface and 0x00ffffff) or (194 shl 24)
   view is EditText->inputPaper
   color in listOf(Color.rgb(24,24,24),Color.rgb(250,250,250),Color.parseColor(OrbitPalette.BG),Color.parseColor(OrbitPalette.LIGHT_BG))->paper
   color in listOf(Color.rgb(48,48,48),Color.rgb(231,231,231),Color.rgb(50,50,50),Color.rgb(36,36,36),Color.parseColor(OrbitPalette.CARD),Color.parseColor(OrbitPalette.LIGHT_CARD))->surface
   color in listOf(Color.rgb(38,38,38),Color.parseColor(OrbitPalette.CARD2),Color.parseColor(OrbitPalette.LIGHT_CARD2))->inputPaper
   else->null
  }
  if(replacement!=null){if(bg is GradientDrawable)bg.setColor(replacement) else view.setBackgroundColor(replacement)}
  if(view is TextView&&view !is Button){
   if(view.currentTextColor in listOf(Color.WHITE,Color.rgb(23,23,23),Color.parseColor(OrbitPalette.INK),Color.parseColor(OrbitPalette.LIGHT_INK)))view.setTextColor(ink)
   if(view.currentTextColor in listOf(Color.LTGRAY,Color.rgb(102,102,102),Color.parseColor(OrbitPalette.MUTED),Color.parseColor(OrbitPalette.LIGHT_MUTED)))view.setTextColor(muted)
   if(view.currentTextColor in listOf(Color.parseColor(OrbitPalette.CYAN),Color.parseColor(OrbitPalette.LIGHT_CYAN)))view.setTextColor(accentText)
   if(view is EditText)view.setHintTextColor(muted)
  }
  if(view is Button&&view !is RadioButton&&view !is ToggleButton&&(view.background!=null||view.tag=="bare-icon"))styleControl(view)
  if(settingsText&&view is TextView&&view !is Button&&view !is EditText)view.setTextColor(ink)
  if(view is android.view.ViewGroup)for(i in 0 until view.childCount)applyAppearance(view.getChildAt(i),settingsText)
  window.statusBarColor=paper;window.navigationBarColor=paper
  window.insetsController?.setSystemBarsAppearance(if(bright)android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS or android.view.WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS else 0,android.view.WindowInsetsController.APPEARANCE_LIGHT_STATUS_BARS or android.view.WindowInsetsController.APPEARANCE_LIGHT_NAVIGATION_BARS)
 }

