 private fun refreshPaletteViews(view:View,oldAccent:Int?=null){
  if(view.background is OrbitWallpaper)view.background.invalidateSelf()
  if(view.tag=="personal-tab"){(view.background as? GradientDrawable)?.setColor(if(view.isSelected)sentPaper else tabIdle)}
  if(view is TextView&&view.tag=="tab-label")view.setTextColor(if((view.parent?.parent as? View)?.isSelected==true)sentInk else ink)
  if(view.tag=="module-shared-line")view.setBackgroundColor(sentPaper)
  if(view.tag=="personal-module")(view.background as? GradientDrawable)?.setColor(sentPaper)
  if(view is TextView&&view.tag=="module-label"){val host=view.parent?.parent as? View;view.setTextColor(if(host?.tag=="personal-tab"&&host.isSelected!=true)ink else sentInk)}
  if(view is TextView&&view.tag=="personal-heading"){
   view.setTextColor(Color.parseColor(palette.optString(if(bright)"headingLight" else "headingDark",if(bright)OrbitPalette.LIGHT_CYAN else OrbitPalette.CYAN)))
   view.setShadowLayer(dp(2).toFloat(),0f,dp(1).toFloat(),if(bright)Color.WHITE else Color.BLACK)
  }
  if(view.tag=="message-body"){
   val mine=(view.parent as? View)?.tag==prefs.getString("id","")
   (view.background as? GradientDrawable)?.setColor(if(mine)sentPaper else receivedPaper)
   tintMessageText(view,if(mine)sentInk else receivedInk)
   return
  }
  if(view is OnceToggle){view.setPair(Color.parseColor(OrbitPalette.CYAN),Color.parseColor(OrbitPalette.BG),inputPaper,accentText);view.foreground=OrbitPalette.focus(this,bright)}
  else if(view is Button&&view !is RadioButton&&view !is ToggleButton&&(view.background!=null||view.tag=="bare-icon"))styleControl(view)

  if(view is Button&&view.contentDescription=="Open Orbit Play")view.setCompoundDrawables(orbitPlayIcon(),null,null,null)
  if(view is ImageView&&view.tag=="chat-call-icon"){view.imageTintList=android.content.res.ColorStateList.valueOf(accentText);view.foreground=OrbitPalette.focus(this,bright)}
  if(view is ImageView&&view.tag=="pair-icon"){
   (view.background as? GradientDrawable)?.setColor(themeIdle);view.imageTintList=android.content.res.ColorStateList.valueOf(themeIdleInk)
  }
  if(view is android.view.ViewGroup)for(i in 0 until view.childCount)refreshPaletteViews(view.getChildAt(i),oldAccent)
 }
