  val owner=prefs.getString("id","")!!;val token=prefs.getString("token","")!!;val base=prefs.getString("server","")!!;if(owner.isEmpty()||token.isEmpty())return;preferenceSyncAt=System.currentTimeMillis();val revision=preferenceRevision
  net.execute {try{val result=ChatApi(base,token).request("/preferences");main.post {if(preferenceRevision==revision&&prefs.getString("id","")==owner&&prefs.getString("token","")==token)rememberPalette(owner,result.getString("palette"))}}catch(_:Exception){}}
