 private fun showConversationSearch(){
  val gen=generation;val target=peer;val dialog=android.app.Dialog(this)
  val panel=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;setPadding(dp(12),dp(12),dp(12),dp(12));background=boundary().apply {setColor(surface)}}
  val heading=LinearLayout(this);heading.addView(text("Search this chat",18f),LinearLayout.LayoutParams(0,-2,1f));heading.addView(button("Close"){dialog.dismiss()});panel.addView(heading)
  val input=field("Words or file name").apply {filters=arrayOf(android.text.InputFilter.LengthFilter(100))};panel.addView(input)
  val status=text("Find messages in this conversation.",12f);panel.addView(status)
  val list=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL};val scroll=ScrollView(this).apply {addView(list)};panel.addView(scroll,LinearLayout.LayoutParams(-1,0,1f))
  fun search(){
   list.removeAllViews();if(screen!="chat"||generation!=gen||peer!=target){dialog.dismiss();return}
   if(firstMessageLoad){status.text="Messages are still loading. Search again shortly.";return}
   val query=input.text.toString().trim();if(query.isEmpty()){status.text="Find messages in this conversation.";return}
   val found=messageValues.values.filter {it.optInt("view_once")==0&&it.optInt("protected_media")==0&&it.optInt("deleted_all")==0&&(it.optString("text").contains(query,true)||it.optString("filename").contains(query,true))}.sortedByDescending {it.optLong("id")}
   status.text=if(found.isEmpty())"No matching messages" else "${found.size} matching messages"+(if(found.size>100)" · showing the latest 100" else "")
   for(m in found.take(100)){
    val date=java.text.DateFormat.getDateTimeInstance(java.text.DateFormat.SHORT,java.text.DateFormat.SHORT).format(java.util.Date(m.optLong("time")))
    list.addView(button((if(m.optString("sender")==prefs.getString("id",""))"You" else peerName)+" · "+date+"\n"+m.optString("text").ifBlank {m.optString("filename")}.take(180)){
     dialog.dismiss();if(screen=="chat"&&generation==gen)messageViews[m.optLong("id")]?.let {row->row.post {(scroller as? LatestMessageScrollView)?.revealPosition(row.top-dp(20));row.foreground=GradientDrawable().apply {setColor(Color.TRANSPARENT);setStroke(dp(2),accentText);cornerRadius=dp(14).toFloat()};row.postDelayed({row.foreground=null},1600)}}
    }.apply {gravity=Gravity.START;textSize=13f})
   }
  }
  panel.addView(button("Search"){search()});input.addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int){};override fun afterTextChanged(s:android.text.Editable?){};override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){search()}})
  dialog.setContentView(panel);dialog.show();dialog.window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.window?.setLayout(-1,(resources.displayMetrics.heightPixels*.65f).toInt());dialog.window?.setGravity(Gravity.TOP);applyAppearance(panel)
 }
 private fun root(title:String,back:(()->Unit)?=null):LinearLayout{
