 private fun covered()=manual || (enabled && latest.coverContent)
 private fun renderProtection(){
  if(privateVibeId!=null&&privateVibeLoaded&&foreground&&!covered()&&!vibeViewed){vibeViewed=true;val ident=privateVibeId;async {api().request("/vibe/view",JSONObject().put("id",ident))}}
  val starting=enabled && latest.state==ProtectionState.INITIALIZING;startupCover?.visibility=if(starting)View.VISIBLE else View.GONE;viewerBody?.visibility=if(starting)View.INVISIBLE else View.VISIBLE;val cover=covered();region?.setProtected(cover);extraRegions.forEach {it.setProtected(cover)}
  status?.visibility=if(cover&&!starting)View.VISIBLE else View.GONE
  status?.text=when {manual->"Hidden manually · tap Hide again to return";!enabled->"GuardianLab off · content is visible";latest.pauseRemainingSeconds>0->"Detection override · ${latest.pauseRemainingSeconds}s · content visible";latest.state==ProtectionState.CLEAR->"Monitoring active · phone and additional-face detection";latest.state==ProtectionState.WAITING_FOR_CLEAR->"Recording device no longer detected · checking that the surroundings stay clear…";latest.state==ProtectionState.CAMERA_VIEW_UNAVAILABLE->"Camera view unusable · improve lighting or uncover lens";latest.state==ProtectionState.MONITORING_UNAVAILABLE->protectionReason;else->"$protectionReason · content hidden"}
  val can=enabled && !manual && latest.state in setOf(ProtectionState.POSSIBLE_DEVICE,ProtectionState.DEVICE_CONFIRMED,ProtectionState.WAITING_FOR_CLEAR,ProtectionState.READY_TO_RESUME)
  notice?.render(cover && can,0L,false)
  if(cover){player?.let {if(it.isPlaying)it.pause()};video?.pause()}else if(privateVibeId!=null&&privateVibeLoaded&&foreground&&!privateVibePaused&&video?.isPlaying==false)video?.start()
 }
