 private fun homeModuleTabs(selected:Int=1):Triple<View,Pair<FrameLayout,TextView>,Pair<FrameLayout,TextView>> {
  val row=LinearLayout(this).apply {gravity=Gravity.CENTER_VERTICAL}
  val play=homeArenaEntry("Play",false){showGaming()}
  val chat=homeArenaEntry("Chat",false,true){homeCalls=false;homeSearch=false;showPeople()}
  val plaza=homeArenaEntry("Plaza",true){showGaming(page="/market.html")}
  val entries=listOf(play,chat,plaza)
  val line=View(this).apply {setBackgroundColor(sentPaper);tag="module-shared-line"}
  var startX=0f;var startY=0f;var started=0L;var dragging=false;var committed=false
  val wrap=object:FrameLayout(this@MainActivity){
   override fun onInterceptTouchEvent(e:MotionEvent):Boolean {
    if(e.actionMasked==MotionEvent.ACTION_DOWN){startX=e.x;startY=e.y;started=android.os.SystemClock.elapsedRealtime();dragging=false}
    if(e.actionMasked==MotionEvent.ACTION_MOVE&&kotlin.math.abs(e.x-startX)>dp(10)&&kotlin.math.abs(e.x-startX)>kotlin.math.abs(e.y-startY)*1.3f){dragging=true;return true}
    return false
   }
   override fun onTouchEvent(e:MotionEvent):Boolean {
    if(!dragging)return super.onTouchEvent(e)
    val dx=e.x-startX;val progress=(selected.toFloat()-dx/width.coerceAtLeast(1)).coerceIn(0f,2f);line.animate().cancel();line.translationX=progress*width/3
    if(e.actionMasked==MotionEvent.ACTION_UP){val elapsed=(android.os.SystemClock.elapsedRealtime()-started).coerceAtLeast(1);val change=kotlin.math.abs(dx)>width*.22f||kotlin.math.abs(dx)>dp(32)&&kotlin.math.abs(dx)/elapsed>dp(1)*.6f;val target=if(change)(selected+if(dx<0)1 else -1).coerceIn(0,2) else selected;line.animate().translationX(target*width/3f).setDuration(motion(180L)).withEndAction {if(target!=selected&&!committed){committed=true;when(target){0->showGaming();2->showGaming(page="/market.html");else->{homeCalls=false;homeSearch=false;showPeople()}}}}.start();dragging=false}
