    };next=if(data.isNull("next_offset"))null else data.getInt("next_offset");more.visibility=if(next==null)View.GONE else View.VISIBLE;feedback.text=if(results.childCount==0)"No matching accounts. Try an exact @nickname or account ID." else "Send a request to connect, or open an existing chat."
