  if(!msg.isNull("fileid")&&msg.optInt("view_once")!=1&&msg.optInt("protected_media")!=1){val attachment=LinearLayout(this).apply {tag="attachment-${msg.optLong("id")}";orientation=LinearLayout.VERTICAL};box.addView(attachment);attachmentMessage(msg,attachment)}

  val time=java.text.DateFormat.getTimeInstance(java.text.DateFormat.SHORT).format(java.util.Date(msg.getLong("time")));outer.addView(box,LinearLayout.LayoutParams(-2,-2));val footer=LinearLayout(this).apply {gravity=Gravity.CENTER_VERTICAL};footer.addView(text(time,11f).apply {typeface=android.graphics.Typeface.create(bodyFont,android.graphics.Typeface.ITALIC);setTextColor(muted)});if(own){val dot=View(this);paintReceipt(dot,msg,msg.optBoolean("pending"));footer.addView(dot,LinearLayout.LayoutParams(dp(7),dp(7)).apply {marginEnd=dp(8)});if(msg.optBoolean("pending")){pendingRows[client]=outer;pendingDots[client]=dot}else receiptDots[msg.getLong("id")]=dot};outer.addView(footer,LinearLayout.LayoutParams(-2,-2))
  messages?.addView(View(this).apply {setBackgroundColor(Color.parseColor("#2e3560"))},LinearLayout.LayoutParams(-1,dp(1)).apply {topMargin=dp(6)});if(msg.optLong("id")>0){messageViews[msg.getLong("id")]=outer;messageValues[msg.getLong("id")]=msg};messageTimes[outer]=msg.optLong("time");messages?.addView(outer,LinearLayout.LayoutParams(-1,-2).apply {topMargin=dp(6);leftMargin=if(own)dp(30) else 0;rightMargin=if(own)0 else dp(30)});applyAppearance(outer);tintMessageText(box,if(own)sentInk else receivedInk);mapSwipeRow(outer,outer);bindMessageActions(outer,msg);groupSenderLabels()
 }
