  if(msg.optString("mime").startsWith("video/")){val gen=generation;val frame=FrameLayout(this);val v=VideoView(this).apply {contentDescription="Preview ${msg.optString("filename")}";setOnClickListener {openAttachment(msg)}};frame.contentDescription="Preview ${msg.optString("filename")}";frame.setOnClickListener {openAttachment(msg)};inlineVideos.add(v);frame.addView(v,FrameLayout.LayoutParams(-1,-1));val toggle=button("▶"){};toggle.setOnClickListener {v.tag=if(v.isPlaying)true else false;if(v.isPlaying)v.pause() else v.start();toggle.text=if(v.isPlaying)"Ⅱ" else "▶"};frame.addView(toggle,FrameLayout.LayoutParams(dp(40),dp(36),Gravity.BOTTOM or Gravity.END));box.addView(frame,LinearLayout.LayoutParams(dp(220),dp(150)));v.setOnPreparedListener {it.isLooping=true;it.setVolume(0f,0f)};val check=object:Runnable{override fun run(){if(gen!=generation)return;val visible=inlineVisible(v);if(visible && v.tag!=true){if(!v.isPlaying)v.start()}else if(v.isPlaying)v.pause();toggle.text=if(v.isPlaying)"Ⅱ" else "▶";main.postDelayed(this,700)}};mediaNet.execute {try{val f=localAttachment(msg);if(!f.exists())api().download(msg.getString("fileid"),f);main.post {if(gen==generation){v.setVideoPath(f.absolutePath);main.post(check)}}}catch(_:Exception){main.post {box.removeView(frame)}}};return}

