 private fun readUprightProfilePhoto(uri:android.net.Uri):Bitmap {
  val source=contentResolver.openInputStream(uri)?.use {BitmapFactory.decodeStream(it,null,BitmapFactory.Options().apply {inSampleSize=4})}?:error("Unable to read photo")
