 private fun showViewer(msg:JSONObject,f:File){if(viewOnceId!=null||protectedSessionId!=null)window.addFlags(WindowManager.LayoutParams.FLAG_SECURE);screen="viewer";generation++;releasePlayback();val root=root(msg.optString("filename").ifEmpty {"View-once content"}){showChat()};val header=root.getChildAt(0) as LinearLayout;if(header.childCount>2)header.removeViewAt(header.childCount-1);(header.getChildAt(1) as TextView).apply {textSize=14f;maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.MARQUEE;isSingleLine=true;isSelected=true};root.setOnApplyWindowInsetsListener {v,i->val bars=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(bars.left,bars.top,bars.right,bars.bottom);i};val body=LinearLayout(this).apply {orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setBackgroundColor(Color.BLACK)}
  
