   }
  }catch(e:Exception){body.removeAllViews();body.addView(text("Preview unavailable. The file can still be saved."))}
  if(viewOnceId!=null||protectedSessionId!=null)protection(root,body) else root.addView(body,LinearLayout.LayoutParams(-1,0,1f));if(mime.startsWith("video/")||mime.startsWith("audio/"))viewerPlaybackControls(root);if(viewOnceId==null&&protectedSessionId==null)root.addView(button("Save a copy outside protection") {android.app.AlertDialog.Builder(this).setTitle("Export file?").setMessage("The saved copy will not be protected by GuardianLab. Other apps can open it.").setNegativeButton("Cancel",null).setPositiveButton("Save copy"){_,_->exportFile=f;startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).apply {type=msg.optString("mime","application/octet-stream");addCategory(Intent.CATEGORY_OPENABLE);putExtra(Intent.EXTRA_TITLE,msg.getString("filename"))},21)}.show()});showContent(root);renderProtection();if(viewOnceId!=null||protectedSessionId!=null){if(foreground)monitor?.start();if(viewOnceId!=null)main.postDelayed(viewLimit,120000)}
 }
