 private fun forwardTextPreview(targets:List<JSONObject>,content:String){draft?.setText(content);previewSend(filename="Message",mime=null,forwardPeers=targets)}
 private fun forwardBatch(targets:List<JSONObject>,content:String,once:Boolean,uri:Uri?,file:File?,filename:String?,mime:String?,noteFile:File?=null,protectedMedia:Boolean=false,onFailure:((List<JSONObject>)->Unit)?=null){
  if(sending)return
  if(protectedMedia&&uri==null&&file==null&&noteFile==null){toast("Attach media to use Protected media");return}
  if(content.isBlank()&&uri==null&&file==null&&noteFile==null){toast("Add a message or attachment");return}
  val senderApi=api();val sentStore=sentAttachments();val gen=generation;sending=true
  async {try{
   val noteData=noteFile?.readBytes()
   val limit=if(mime?.startsWith("video/")==true)30*1024*1024 else 8*1024*1024
   val attachment=if(uri!=null)readLimited(uri,limit)else file?.readBytes()
   check(attachment==null||attachment.size<=limit){"Video limit is 30 MB; other files 8 MB"}
   val failed=mutableListOf<JSONObject>()
   for(target in targets){try{
    val client=target.optString("forward_client").ifEmpty {UUID.randomUUID().toString().also {target.put("forward_client",it)}}
    val body=JSONObject().put("peer",target.getString("id")).put("text",content).put("view_once",once).put("protected_media",protectedMedia).put("client_id",client)
    if(attachment!=null)body.put("data",android.util.Base64.encodeToString(attachment,android.util.Base64.NO_WRAP)).put("filename",filename).put("mime",mime)
    if(attachment!=null||content.isNotBlank()&&!protectedMedia)uploadSentMessage(senderApi,sentStore,body,attachment)
    if(noteData!=null)uploadSentMessage(senderApi,sentStore,JSONObject().put("peer",target.getString("id")).put("text",if(attachment==null)content else "").put("view_once",once).put("client_id",client+"-voice").put("protected_media",protectedMedia).put("data",android.util.Base64.encodeToString(noteData,android.util.Base64.NO_WRAP)).put("filename","Voice note.m4a").put("mime","audio/mp4"),noteData)
   }catch(_:Exception){failed.add(target)}}
   main.post {if(gen==generation&&senderApi.token==prefs.getString("token","")&&senderApi.base==prefs.getString("server","")){
    if(failed.isEmpty()){clearPreview();draft?.text?.clear();onceChoice?.isChecked=false;toast(if(targets.size==1)"Sent" else "Forwarded to ${targets.size} contacts");revealLatestChat();fetchMessages()}
    else{toast("Not sent to "+failed.joinToString {it.getString("name")});if(onFailure!=null)onFailure(failed)else if(file!=null||uri!=null){val retry=file?.let {File(cacheDir,"forward-${UUID.randomUUID()}-${filename?:"attachment"}").also {copy->it.copyTo(copy,true)}};draft?.setText(content);onceChoice?.isChecked=once;previewSend(uri,retry,filename?:"Attachment",mime,failed)}else forwardTextPreview(failed,content)}
   }}
  }finally{main.post {sending=false}}}
 }

